os.environ['SOL_SOURCE_REVISION']='af579a3590ce8e598ba40fedb77080a2b908f8ee'
root=Path('/kaggle/working/code');root.mkdir(exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(''))) as tar:tar.extractall(root)
